| 1 = {{TrekkerPotential
  | name = Crystal Overclock
  | type = 1
  | brief = No longer generates Observation Points. Auto Attacks can consume {{word|Resource Markers|}} to increase that attack's DMG multiplier.
  | desc = After casting Crystal Vein Survey (Main Skill), Observation Points are no longer generated. When Leafia's Auto Attack deals DMG, it always generates 1 Resource Marker. Leafia's Auto Attack can also consume 3 {{word|Resource Markers|}} to fire an Amplification Crystal, dealing {{color|#0abec5|119%}} of ATK as Terra Auto Attack DMG, increasing that Auto Attack's DMG multiplier by {{color|#0abec5|50%}}, and triggering {{word|Terra Mark|earth}}.
  | icon = 16101_potential_01_a.png
  | shape = 0
  }}
  {{TrekkerPotential
  | name = Focused Penetration
  | type = 1
  | brief = Auto Attacks generate extra {{word|Resource Markers|}} when dealing DMG. Auto Attack's DMG multiplier is increased and pierces targets. Any new {{word|Resource Markers|}} are absorbed automatically.
  | desc = Leafia's Auto Attacks generate 1 extra Resource Marker when dealing DMG. Auto Attack's DMG multiplier is increased by {{color|#0abec5|70%}} and pierces targets. Any new {{word|Resource Markers|}} are absorbed automatically.
  | icon = 16101_potential_02_a.png
  | shape = 0
  }}
  {{TrekkerPotential
  | name = Marker Overload
  | type = 2
  | brief = Increases Leafia's Auto Attack DMG. Firing Amplification Crystals has a chance to launch an extra Vector Crystal without using {{word|Resource Markers|}}. Firing Amplification Crystals costs less Resource Marker.
  | desc = Increases Leafia's Auto Attack DMG by {{color|#ec6d21|20%/32%/44%/56%/68%/80%}}. Firing Amplification Crystals has an 80% chance to launch an extra Vector Crystal without using {{word|Resource Markers|}}, dealing {{color|#ec6d21|10.9%/17.4%/23.9%/30.4%/36.9%/43.4%}} of ATK as Terra Auto Attack DMG. Firing Amplification Crystals costs 1 less Resource Marker.
  | icon = 16101_potential_07_a.png
  | shape = 3
  }}
  {{TrekkerPotential
  | name = Terra DMG Amp
  | type = 3
  | brief = When Amplification Crystals deal DMG, increases the targets' Terra DMG Taken.
  | desc = When Amplification Crystals deal DMG, increases the targets' Terra DMG Taken by {{color|#ec6d21|0.8%/1.3%/1.8%/2.2%/2.7%/3.2%}} for 5s, stacking up to 10 times.
  | icon = 16101_potential_01_a.png
  | shape = 1
  }}
  {{TrekkerPotential
  | name = Terra Mark Resonance
  | type = 3
  | brief = When Amplification Crystals trigger a {{word|Terra Mark|earth}}, increases Leafia's ATK.
  | desc = When Amplification Crystals trigger a {{word|Terra Mark|earth}}, increases Leafia's ATK by {{color|#ec6d21|1.5%/2.4%/3.3%/4.2%/5.1%/6%}} for 10s, stacking up to 10 times.
  | icon = 16101_potential_01_a.png
  | shape = 2
  }}
| 2 = {{TrekkerPotential
  | name = Field Echo
  | type = 1
  | brief = Auto Attacks no longer generate {{word|Resource Markers|}} when dealing DMG. Reduces Main Skill Cooldown and extends Observation Point duration. Each Observation Point deals additional DMG every 3 attacks.
  | desc = Auto Attacks no longer generate {{word|Resource Markers|}} when dealing DMG. Reduces Main Skill Cooldown by {{color|#0abec5|10s}} and extends Observation Point duration by {{color|#0abec5|20s}}. Casting a skill directly generates 1 Observation Point without consuming {{word|Resource Markers|}} (triggers once every 20s). Every {{color|#0abec5|3}} attacks, each Observation Point releases a wave that deals {{color|#0abec5|103%}} of ATK as AoE Terra Auto Attack DMG.
  | icon = 16101_potential_03_a.png
  | shape = 0
  }}
  {{TrekkerPotential
